contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We will set MinSum and LogFile before any initialization, then deposit, then try Collect.
    // Parameters: depositAmount to put into c, collectAmount to attempt to withdraw.
    function run(uint depositAmount, uint collectAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);

        // Configure C while it's still configurable
        c.SetMinSum(0); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        // Do NOT call Initialized() so the contract remains in configurable state in case that matters.

        // Deposit into c so this test contract has an on-chain balance recorded by c
        c.Deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // Snapshot balances before Collect
        uint beforeBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // Require precondition for the rule: MinSum (we set 0) must be <= beforeBal and beforeBal >= collectAmount
        // Also require that collectAmount is not absurdly large to avoid underflow in the asserted relation.
        require(beforeBal >= collectAmount);

        bool reverted;
        c.Collect(collectAmount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBal = c.balances(address(this)); if (__ESBMC_reverted()) return;

        // General rule: if Collect did not revert, then the recorded balance decreased exactly by collectAmount.
        // (This focuses on c.balances behavior when Collect succeeds under the stated preconditions.)
        assert(reverted || afterBal + collectAmount == beforeBal);
    }

    // Accept any Ether sent back from C
    receive() external payable {}
}

